import datetime

class TimestampedRecord:
    def __init__(self, data):
        self.data = data
        self.created = datetime.datetime.now()

    def __eq__(self, other):
        if not isinstance(other, TimestampedRecord):
            return NotImplemented
        return self.data == other.data

    def __str__(self):
        return f'Record created at {self.created.strftime("%Y-%m-%d %H:%M")}: {self.data}'

    def __repr__(self):
        return f'TimestampedRecord({self.data!r})'
